import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"08 - Historify","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/utilities.md","filePath":"developers/design-documentation/utilities.md"}'),d={name:"developers/design-documentation/utilities.md"};function r(o,e,n,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="_08-historify" tabindex="-1">08 - Historify <a class="header-anchor" href="#_08-historify" aria-label="Permalink to &quot;08 - Historify&quot;">​</a></h1><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>Historify is the local historical-data subsystem. The React <code>/historify</code> page calls a session-authenticated Flask blueprint under <code>/historify/api</code>; download services use the logged-in user&#39;s Tradeboard API key to fetch normalized broker history and persist it in DuckDB.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>React /historify</span></span>
<span class="line"><span>  -&gt; /historify/api routes</span></span>
<span class="line"><span>  -&gt; historify service / scheduler service</span></span>
<span class="line"><span>  -&gt; normalized history service</span></span>
<span class="line"><span>  -&gt; broker API</span></span>
<span class="line"><span>  -&gt; DuckDB + catalog/job state</span></span></code></pre></div><p>Historify is not part of the Flask-RESTX <code>/api/v1</code> namespace. <code>/api/v1/history</code> can read its DuckDB data with <code>source=db</code>, but Historify administration remains session-authenticated.</p><h2 id="duckdb-ownership" tabindex="-1">DuckDB Ownership <a class="header-anchor" href="#duckdb-ownership" aria-label="Permalink to &quot;DuckDB Ownership&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th></tr></thead><tbody><tr><td><code>market_data</code></td><td>OHLCV/OI candles keyed by symbol, exchange, interval, timestamp</td></tr><tr><td><code>watchlist</code></td><td>Unique tracked symbol/exchange entries</td></tr><tr><td><code>data_catalog</code></td><td>Stored range and record-count metadata</td></tr><tr><td><code>download_jobs</code></td><td>Asynchronous job status/configuration</td></tr><tr><td><code>job_items</code></td><td>Per-symbol job status and errors</td></tr><tr><td><code>symbol_metadata</code></td><td>Expiry, strike, lot, type, and tick metadata</td></tr><tr><td><code>historify_schedules</code></td><td>Recurring watchlist download definitions</td></tr><tr><td><code>historify_schedule_executions</code></td><td>Per-run schedule history</td></tr></tbody></table><p>Connections are context-managed and retry transient file-lock conflicts. The default path is <code>db/historify.duckdb</code>.</p><p>Historify&#39;s configured database file is <code>HISTORIFY_DATABASE_PATH</code>, defaulting to <code>db/historify.duckdb</code>. The obsolete <code>HISTORIFY_DATABASE_URL</code> spelling is not a runtime alias.</p><h2 id="runtime-features" tabindex="-1">Runtime Features <a class="header-anchor" href="#runtime-features" aria-label="Permalink to &quot;Runtime Features&quot;">​</a></h2><ul><li>Watchlist CRUD and bulk changes.</li><li>Single/watchlist downloads.</li><li>Multi-symbol jobs with pause, resume, cancel, retry, incremental ranges, and Socket.IO progress.</li><li>Chart queries, catalog/statistics, dataset deletion, and metadata enrichment.</li><li>CSV/Parquet upload plus CSV, TXT, ZIP, and Parquet export.</li><li>F&amp;O underlying, expiry, futures, options, and chain discovery.</li><li>Interval/daily schedules backed by APScheduler and persisted execution history.</li></ul><p>Jobs use a bounded thread pool. Active persisted jobs without matching process-local state after restart are marked failed so they can be retried.</p><h2 id="intervals" tabindex="-1">Intervals <a class="header-anchor" href="#intervals" aria-label="Permalink to &quot;Intervals&quot;">​</a></h2><p><code>1m</code> and <code>D</code> are the primary downloaded/storage intervals. Historify can aggregate supported higher and calendar intervals from stored candles for query/export workflows. The exact supported list is exposed by <code>/historify/api/historify-intervals</code> rather than maintained as a hard-coded documentation list.</p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>blueprints/historify.py</code></td><td>Session routes and complete <code>/historify/api</code> surface</td></tr><tr><td><code>services/historify_service.py</code></td><td>Download, query, export, import, and job logic</td></tr><tr><td><code>services/historify_scheduler_service.py</code></td><td>Recurring schedules</td></tr><tr><td><code>database/historify_db.py</code></td><td>DuckDB schema and operations</td></tr><tr><td><code>frontend/src/pages/Historify.tsx</code></td><td>React manager</td></tr></tbody></table><p>See the public <a href="./../../new-features/historify.html">Historify guide</a>.</p>`,17)])])}const y=t(d,[["render",r]]);export{p as __pageData,y as default};
